package tv.plus.pro.unified;
import android.app.*;import android.os.*;import android.content.*;import android.graphics.Color;import android.graphics.drawable.GradientDrawable;import android.hardware.usb.*;import android.os.storage.*;import android.view.*;import android.widget.*;import java.util.*;
public class DesktopVmActivity extends Activity {
 LinearLayout body; TextView status; int blue=0xff101d43;
 TextView label(String s,int size){TextView t=new TextView(this);t.setText(s);t.setTextColor(-1);t.setTextSize(size);t.setPadding(18,13,18,13);return t;}
 GradientDrawable panel(){GradientDrawable d=new GradientDrawable(GradientDrawable.Orientation.TL_BR,new int[]{0xff192c5c,0xff49286f});d.setCornerRadius(24);return d;}
 void action(String s,Runnable r){TextView t=label(s,17);t.setBackground(panel());t.setFocusable(true);t.setOnClickListener(v->r.run());LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.setMargins(8,7,8,7);body.addView(t,p);}
 @Override public void onCreate(Bundle b){super.onCreate(b);getWindow().getDecorView().setSystemUiVisibility(5894|1024|512);showDesktop(); }
 void showDesktop(){LinearLayout root=new LinearLayout(this);root.setOrientation(1);root.setPadding(18,18,18,18);root.setBackgroundColor(0xff080e25);TextView top=label("TV+ Desktop  •  USB Workspace",23);top.setTypeface(null,1);root.addView(top);status=label("USB aygıtları taranıyor…",13);root.addView(status);ScrollView scroll=new ScrollView(this);body=new LinearLayout(this);body.setOrientation(1);scroll.addView(body);root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));setContentView(root);root.setAlpha(0f);root.animate().alpha(1f).setDuration(380).start();refresh();}
 void refresh(){body.removeAllViews();action("↻  USB aygıtlarını yeniden tara",()->refresh());action("⌂  TV+ ana ekranına dön",()->finish());UsbManager um=(UsbManager)getSystemService(USB_SERVICE);HashMap<String,UsbDevice> devices=um.getDeviceList();int count=0;for(UsbDevice d:devices.values()){count++;String title="USB  "+d.getDeviceName()+"  •  VID "+d.getVendorId()+" / PID "+d.getProductId();action(title,()->new AlertDialog.Builder(this).setTitle("USB Aygıtı").setMessage("Üretici ID: "+d.getVendorId()+"\nÜrün ID: "+d.getProductId()+"\nArayüz sayısı: "+d.getInterfaceCount()+"\nAndroid USB izni: "+(um.hasPermission(d)?"Var":"Yok")+"\n\nBu ekran USB aygıtını tanır; USB'deki işletim sistemini henüz başlatmaz.").setPositiveButton("Tamam",null).show());}
 StorageManager sm=(StorageManager)getSystemService(STORAGE_SERVICE);for(StorageVolume v:sm.getStorageVolumes()){if(!v.isRemovable())continue;count++;String name=v.getDescription(this);action("▣  USB depolama: "+name,()->new AlertDialog.Builder(this).setTitle(name).setMessage("Durum: "+v.getState()+"\n\nAndroid dosya seçicisiyle erişilebilir içerikleri açabilirsin. Bu işlem USB'den işletim sistemi başlatmaz.").setPositiveButton("Dosya seç",(dialog,w)->{Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT);i.setType("*/*");i.addCategory(Intent.CATEGORY_OPENABLE);try{startActivity(i);}catch(Exception e){Toast.makeText(this,"Dosya seçici açılamadı",0).show();}}).setNegativeButton("Kapat",null).show());}
 boolean keyboard=false,mouse=false;for(int id:InputDevice.getDeviceIds()){InputDevice dev=InputDevice.getDevice(id);if(dev==null)continue;int src=dev.getSources();if((src&InputDevice.SOURCE_KEYBOARD)==InputDevice.SOURCE_KEYBOARD&&dev.isExternal())keyboard=true;if((src&InputDevice.SOURCE_MOUSE)==InputDevice.SOURCE_MOUSE&&dev.isExternal())mouse=true;}
 status.setText("Klavye: "+(keyboard?"Bağlı":"Algılanmadı")+"   •   Fare: "+(mouse?"Bağlı":"Algılanmadı")+"   •   USB: "+count);
 action("⚙  VM yapılandırması",()->vmConfig());action("▶  VM motorunu kontrol et",()->vmEngineStatus());action("▣  Sanal makine durumu",()->new AlertDialog.Builder(this).setTitle("VM motoru gerekli").setMessage("Bu sürümde masaüstü çalışma alanı ve USB keşfi bulunur. Gerçek Linux/Windows USB boot, QEMU gibi uyumlu bir VM motoru olmadan çalışmaz. USB aygıtlarını Android'den tamamen ayırmak da standart APK izniyle mümkün değildir.").setPositiveButton("Anladım",null).show());}
 void vmConfig(){final String[] ram={"128 MB","256 MB","512 MB","1024 MB"};final int[] values={128,256,512,1024};int saved=getSharedPreferences("tvplus_vm",0).getInt("ram",256);int selected=1;for(int i=0;i<values.length;i++)if(values[i]==saved)selected=i;new AlertDialog.Builder(this).setTitle("VM RAM sınırı (yapılandırma)").setSingleChoiceItems(ram,selected,(d,n)->{getSharedPreferences("tvplus_vm",0).edit().putInt("ram",values[n]).apply();d.dismiss();Toast.makeText(this,"VM RAM ayarı: "+ram[n],Toast.LENGTH_SHORT).show();}).setNegativeButton("Kapat",null).show();}
 void vmEngineStatus(){String[] arch=Build.SUPPORTED_ABIS;String abi=arch.length>0?arch[0]:"Bilinmiyor";int ram=getSharedPreferences("tvplus_vm",0).getInt("ram",256);String info="Cihaz mimarisi: "+abi+"\\nAndroid: "+Build.VERSION.RELEASE+"\\nPlanlanan VM RAM: "+ram+" MB\\n\\nQEMU motoru: Yüklü değil\\nVM disk görüntüsü: Seçilmedi\\n\\nBu APK henüz gerçek VM başlatamaz. İşlemciye uygun QEMU native motoru ve görüntü aktarımı eklendikten sonra başlatma açılacak.";new AlertDialog.Builder(this).setTitle("VM Motoru • Uyumluluk").setMessage(info).setPositiveButton("Tamam",null).show();}
 @Override public void onBackPressed(){finish();}
}
